from pathlib import Path
import hashlib,json
root=Path('/mnt/data/full_work_package/SR-Foxy')
records=[]
def save(path, content, sha):
    b=content.encode('utf-8')
    actual=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
    if actual != sha:
        raise ValueError(f'{path}: {actual} != {sha}')
    p=root/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(b)
    records.append({'path':path,'git_blob_sha1':sha,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)})
